{"thought": "I have the full spec. Now let me implement the Kruskal's algorithm with Union-Find. Key requirements: 1) Sort by km, 2) Use Union-Find to detect cycles, 3) Ignore self-loops, 4) Normalize edges (alphabetically smaller first), 5) Sort result by (km, first_code, second_code), 6) Handle disconnected graph (spanning forest).", "action": {"tool": "write_file", "args": {"path": "src/routekit/min_spanning_tree.py", "content": "from __future__ import annotations

from typing import Iterable, List, Tuple


def min_spanning_tree(edges: Iterable[Tuple[str, str, int]]) -> List[Tuple[str, str, int]]:
    """
    Select the cheapest set of roads that keeps every region connected (Kruskal).

    Roads are undirected ``(from_code, to_code, km)`` tuples. Roads are considered in
    order of increasing km, and a road is kept if it joins two depots that are not yet
    connected by previously kept roads. For a disconnected network the result is a
    spanning forest (one tree per region). Self-loops are ignored.

    Every returned road is normalised so that its first code is alphabetically smaller
    than the second, and the result is sorted by ``(km, first_code, second_code)``.
    An empty input gives ``[]``.

    Example:
        min_spanning_tree([("HAM", "BER", 289), ("BER", "LEI", 190), ("HAM", "LEI", 395)])
            == [("BER", "LEI", 190), ("BER", "HAM", 289)]
    """
    # Filter out self-loops and normalise edges
    normalised: List[Tuple[str, str, int]] = []
    for a, b, km in edges:
        if a == b:
            continue
        if a < b:
            normalised.append((a, b, km))
        else:
            normalised.append((b, a, km))

    # Sort by (km, first_code, second_code)
    normalised.sort(key=lambda e: (e[2], e[0], e[1]))

    # Union-Find with path compression and union by rank
    parent: dict[str, str] = {}
    rank: dict[str, int] = {}

    def find(x: str) -> str:
        if x not in parent:
            parent[x] = x
            rank[x] = 0
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # path compression (halving)
            x = parent[x]
        return x

    def union(x: str, y: str) -> bool:
        """Return True if x and y were in different sets (now merged)."""
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    result: List[Tuple[str, str, int]] = []
    for a, b, km in normalised:
        if union(a, b):
            result.append((a, b, km))

    return result
