def shortest_path(adj: Mapping[str, Mapping[str, int]], src: str, dst: str) -> Optional[Tuple[int, List[str]]]:
    """
    Find the shortest route by road length between two depots.

    ``adj`` is an adjacency map as built by ``build_adjacency`` (directed or not) with
    non-negative km values. Returns ``(total_km, path)`` where ``path`` lists the depot
    codes from ``src`` to ``dst`` inclusive; ``src == dst`` gives ``(0, [src])``.
    Returns None when ``dst`` cannot be reached from ``src``.

    Real networks often contain several routes of equal length; the function must
    always return the same route for the same network, independent of dict insertion
    order.

    Raises KeyError if ``src`` or ``dst`` is not a key of ``adj``.

    Example:
        net = {"A": {"B": 2}, "B": {"A": 2, "C": 3}, "C": {"B": 3}}
        shortest_path(net, "A", "C") == (5, ["A", "B", "C"])
    """
    if src not in adj:
        raise KeyError(src)
    if dst not in adj:
        raise KeyError(dst)

    if src == dst:
        return (0, [src])

    # Dijkstra with heap entries (total_km, path_list, node).
    # The path_list in the heap key gives deterministic tie-breaking:
    #   1. Fewer total km wins.
    #   2. Among equal km, the lexicographically smallest path list wins,
    #      which also covers the "fewer legs" rule (a shorter list is a
    #      prefix and thus lexicographically smaller when the longer list
    #      extends it; in general the lex order handles both cases).
    # We keep the best (smallest) path to each node and prune dominated entries.

    best: Dict[str, Tuple[int, List[str]]] = {src: (0, [src])}
    heap: List[Tuple[int, List[str], str]] = [(0, [src], src)]

    while heap:
        d, path, node = heapq.heappop(heap)

        # Skip if we already have a strictly better (or equal) record for node.
        prev = best.get(node)
        if prev is not None:
            if d > prev[0]:
                continue
            if d == prev[0] and path >= prev[1]:
                continue

        # This entry is the new best for node.
        best[node] = (d, path)

        if node == dst:
            return (d, path)

        for nbr, w in adj[node].items():
            nd = d + w
            npath = path + [nbr]
            # Prune dominated neighbours before pushing.
            prevn = best.get(nbr)
            if prevn is not None:
                if nd > prevn[0]:
                    continue
                if nd == prevn[0] and npath >= prevn[1]:
                    continue
            heapq.heappush(heap, (nd, npath, nbr))

