    )
    removed = sorted(
        [(f, t, km) for f, t, km in old_edges if (f, t) not in new_keys]
    )

    old_map = {(f, t): km for f, t, km in old_edges}
    new_map = {(f, t): km for f, t, km in new_edges}

    changed = sorted(
        [(f, t, new_map[(f, t)]) for f, t in old_keys & new_keys if old_map[(f, t)] != new_map[(f, t)]]
    )

    return {"added": added, "removed": removed, "changed": changed}
